        "description": "There are places where everything just comes together. That's Regenta Suites, Gurugram for you. \nIt sits within Element One Mall on Golf Course Extension Road. This might seem like a mundane detail until you realise it means great restaurants, shopping, and entertainment are literally at your doorstep. No need to book cabs. No planning required. Just get up and go. \nThe suites are generously sized. Even the smallest will pleasantly surprise you with the space and if you go for one of the larger ones, you will start wondering why you will ever book anything else. Modern, comfortable, well-appointed, the kind of room you don't feel boxed in. \nHungry? The all-day dining has you covered, whether you want a proper spread or something light. When you're done eating, head to the rooftop, the biggest in the city, and marvel at the twinkling lights of the skyline spread out in front of you. \nIf you're in town for work, the meeting and event spaces are serious. Pillarless halls, over 5,000 sq. ft. of convention space, and the ability to go from a 20-person boardroom to a 200-person dinner, without leaving the building. \nThe best way to describe Regenta Suites is this: it's one of those places that makes a city feel easy. Everything's here. Everything works. And at the end of a long day or a long event, or a long shopping run, that's exactly what you want.",
