        "description": "Located close to the UNESCO World Heritage Site of Hampi, Hotel Royal Orchid Central Kireeti, Hospet, is favoured by history buffs and heritage lovers. One of the best hotels near Hampi and the famous Virupaksha Temple, it offers 120 comfortable rooms in the city's heart and easy access to the Hampi ruins. Conveniently located within walking distance of the Hosapete Railway Station, it also offers excellent connectivity to Hampi monuments and the Daroji Sloth Bear Sanctuary. \nOne of the top hotels in Hospet, it indulges the guests with two Food and Beverage outlets. Mix, the contemporary lounge bar, is perfect for a sundowner, and Echo, the hotel’s all-day dining restaurant, is popular with both in-house and walk-in guests for its variety of F&B options. \nThe hotel also features a Banquet Hall, a Lawn and a Boardroom, making it the city’s preferred choice for weddings, celebrations and corporate events. \nHotel Royal Orchid Central Kireeti, Hospet, has been at the forefront of high-profile events and hosted two G20 meetings in 2023. Prime Minister Narendra Modi also preferred the hotel for a stay during his visit to Hampi in 2024.",
